-- PhotoDuel schema v1. Forward-only. The migration runner records a SHA-256 checksum per file in
-- schema_migrations and refuses to start when an applied file has been edited.
--
-- Times are timestamptz written from the server clock (the API passes its injected clock value),
-- never from a client. Ids are UUID v4 generated by the server.

CREATE TABLE users (
    id               uuid PRIMARY KEY,
    display_name     text,                       -- NULL once the account is deleted
    created_at       timestamptz NOT NULL,
    suspended_at     timestamptz,
    suspended_reason text,
    deleted_at       timestamptz,
    CONSTRAINT users_name_present CHECK (deleted_at IS NOT NULL OR display_name IS NOT NULL),
    CONSTRAINT users_name_cleared CHECK (deleted_at IS NULL OR display_name IS NULL)
);

-- Only the SHA-256 of the bearer token is stored. The token itself never reaches the database.
CREATE TABLE sessions (
    token_hash   bytea PRIMARY KEY CHECK (octet_length(token_hash) = 32),
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   timestamptz NOT NULL,
    last_used_at timestamptz NOT NULL,
    expires_at   timestamptz NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expiry_idx ON sessions (expires_at);

-- One recovery code per user, rotated on every issue and on every successful restore.
-- code_hash is scrypt(code) with a fixed application salt so that a restore can find the row by
-- index; the code itself is 80 random bits, so per-row salts add nothing against precomputation.
CREATE TABLE recovery_codes (
    user_id    uuid PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    code_hash  bytea NOT NULL UNIQUE,
    created_at timestamptz NOT NULL
);

CREATE TABLE rooms (
    id              uuid PRIMARY KEY,
    name            text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 40),
    owner_id        uuid NOT NULL REFERENCES users (id),
    capacity        integer NOT NULL DEFAULT 8 CHECK (capacity BETWEEN 2 AND 8),
    created_at      timestamptz NOT NULL,
    deleted_at      timestamptz,
    media_purged_at timestamptz
);
CREATE INDEX rooms_owner_idx ON rooms (owner_id);
CREATE INDEX rooms_deleted_idx ON rooms (deleted_at) WHERE deleted_at IS NOT NULL;

-- Membership history. Exactly one active row (left_at IS NULL) per room and user.
CREATE TABLE room_members (
    id        uuid PRIMARY KEY,
    room_id   uuid NOT NULL REFERENCES rooms (id) ON DELETE CASCADE,
    user_id   uuid NOT NULL REFERENCES users (id),
    role      text NOT NULL CHECK (role IN ('OWNER', 'MEMBER')),
    joined_at timestamptz NOT NULL,
    left_at   timestamptz,
    left_reason text CHECK (left_reason IN ('LEFT', 'REMOVED', 'ACCOUNT_DELETED', 'ROOM_DELETED'))
);
CREATE UNIQUE INDEX room_members_one_active ON room_members (room_id, user_id) WHERE left_at IS NULL;
CREATE INDEX room_members_user_idx ON room_members (user_id) WHERE left_at IS NULL;

CREATE TABLE invitations (
    id         uuid PRIMARY KEY,
    room_id    uuid NOT NULL REFERENCES rooms (id) ON DELETE CASCADE,
    token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    created_by uuid NOT NULL REFERENCES users (id),
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    max_uses   integer NOT NULL CHECK (max_uses >= 1),
    uses       integer NOT NULL DEFAULT 0 CHECK (uses >= 0 AND uses <= max_uses),
    revoked_at timestamptz
);
CREATE INDEX invitations_room_idx ON invitations (room_id);

CREATE TABLE challenges (
    id                  uuid PRIMARY KEY,
    room_id             uuid NOT NULL REFERENCES rooms (id) ON DELETE CASCADE,
    round_number        integer NOT NULL CHECK (round_number >= 1),
    prompt_id           text NOT NULL,
    prompt_title        text NOT NULL,
    prompt_brief        text NOT NULL,
    state               text NOT NULL CHECK (state IN
                          ('CREATED', 'OPEN_FOR_SUBMISSIONS', 'VOTING', 'COMPLETED', 'ARCHIVED', 'CANCELLED')),
    outcome             text CHECK (outcome IN
                          ('WINNER', 'TIE', 'INSUFFICIENT_SUBMISSIONS', 'INSUFFICIENT_BALLOTS')),
    submission_hours    integer NOT NULL CHECK (submission_hours IN (1, 6, 24, 48, 72)),
    voting_hours        integer NOT NULL CHECK (voting_hours IN (1, 6, 24)),
    created_by          uuid REFERENCES users (id),
    created_at          timestamptz NOT NULL,
    started_at          timestamptz,
    submission_deadline timestamptz,
    voting_deadline     timestamptz,
    completed_at        timestamptz,
    archived_at         timestamptz,
    cancelled_at        timestamptz,
    media_purged_at     timestamptz,
    UNIQUE (room_id, round_number),
    CONSTRAINT challenges_deadlines_set CHECK (
        state IN ('CREATED') OR (state = 'CANCELLED')
        OR (started_at IS NOT NULL AND submission_deadline IS NOT NULL AND voting_deadline IS NOT NULL)
    ),
    CONSTRAINT challenges_outcome_when_done CHECK (
        (state IN ('COMPLETED', 'ARCHIVED')) = (outcome IS NOT NULL)
    )
);
-- At most one challenge per room in CREATED, OPEN_FOR_SUBMISSIONS or VOTING.
CREATE UNIQUE INDEX challenges_one_active_per_room ON challenges (room_id)
    WHERE state IN ('CREATED', 'OPEN_FOR_SUBMISSIONS', 'VOTING');
CREATE INDEX challenges_open_due_idx ON challenges (submission_deadline) WHERE state = 'OPEN_FOR_SUBMISSIONS';
CREATE INDEX challenges_voting_due_idx ON challenges (voting_deadline) WHERE state = 'VOTING';
CREATE INDEX challenges_completed_idx ON challenges (completed_at) WHERE state = 'COMPLETED';

-- Roster frozen when the challenge starts. Rows are never added afterwards.
CREATE TABLE roster (
    challenge_id uuid NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users (id),
    PRIMARY KEY (challenge_id, user_id)
);
CREATE INDEX roster_user_idx ON roster (user_id);

CREATE TABLE media (
    id           uuid PRIMARY KEY,
    owner_id     uuid REFERENCES users (id),          -- NULL once the owner deletes the account
    challenge_id uuid NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,
    variant      text NOT NULL CHECK (variant IN ('FULL', 'THUMBNAIL')),
    storage_key  text NOT NULL UNIQUE,
    sha256       text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    mime         text NOT NULL CHECK (mime = 'image/jpeg'),
    width        integer NOT NULL CHECK (width > 0),
    height       integer NOT NULL CHECK (height > 0),
    byte_size    integer NOT NULL CHECK (byte_size > 0),
    created_at   timestamptz NOT NULL,
    purged_at    timestamptz
);
CREATE INDEX media_challenge_idx ON media (challenge_id);
CREATE INDEX media_owner_idx ON media (owner_id);

CREATE TABLE submissions (
    id             uuid PRIMARY KEY,
    challenge_id   uuid NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,
    author_id      uuid REFERENCES users (id),         -- NULL once the author deletes the account
    status         text NOT NULL CHECK (status IN ('ACTIVE', 'WITHDRAWN', 'REMOVED', 'HIDDEN')),
    full_media_id  uuid NOT NULL REFERENCES media (id),
    thumb_media_id uuid NOT NULL REFERENCES media (id),
    width          integer NOT NULL,
    height         integer NOT NULL,
    created_at     timestamptz NOT NULL,
    updated_at     timestamptz NOT NULL,
    hidden_at      timestamptz,
    hidden_reason  text
);
-- One live submission (ACTIVE or HIDDEN) per challenge and author.
CREATE UNIQUE INDEX submissions_one_live ON submissions (challenge_id, author_id)
    WHERE status IN ('ACTIVE', 'HIDDEN');
CREATE INDEX submissions_author_idx ON submissions (author_id);
CREATE INDEX submissions_full_media_idx ON submissions (full_media_id);
CREATE INDEX submissions_thumb_media_idx ON submissions (thumb_media_id);

-- Ballots. A PostgreSQL primary key cannot contain NULL, and voter_id must become NULL when a voter
-- deletes the account, so the "one ballot per voter" rule is a UNIQUE constraint on
-- (challenge_id, voter_id). Two live voters can never share a row; anonymised ballots (NULL) stay.
CREATE TABLE votes (
    id            uuid PRIMARY KEY,
    challenge_id  uuid NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,
    voter_id      uuid REFERENCES users (id),
    submission_id uuid NOT NULL REFERENCES submissions (id) ON DELETE CASCADE,
    cast_at       timestamptz NOT NULL,
    CONSTRAINT votes_one_per_voter UNIQUE (challenge_id, voter_id)
);
CREATE INDEX votes_submission_idx ON votes (submission_id);

-- The tally is written once per challenge; the primary key makes the computation idempotent.
CREATE TABLE challenge_results (
    challenge_id                uuid PRIMARY KEY REFERENCES challenges (id) ON DELETE CASCADE,
    outcome                     text NOT NULL CHECK (outcome IN
                                  ('WINNER', 'TIE', 'INSUFFICIENT_SUBMISSIONS', 'INSUFFICIENT_BALLOTS')),
    co_winner_submission_ids    jsonb NOT NULL,
    tallies                     jsonb NOT NULL,
    ballot_count                integer NOT NULL,
    eligible_voter_count        integer NOT NULL,
    computed_at                 timestamptz NOT NULL
);

CREATE TABLE reports (
    id          uuid PRIMARY KEY,
    reporter_id uuid NOT NULL REFERENCES users (id),
    target_type text NOT NULL CHECK (target_type IN ('SUBMISSION', 'USER')),
    target_id   uuid NOT NULL,
    reason      text NOT NULL CHECK (reason IN
                  ('INAPPROPRIATE', 'HARASSMENT', 'PRIVACY', 'SPAM', 'NOT_A_PHOTO_OF_PROMPT', 'OTHER')),
    details     text CHECK (details IS NULL OR char_length(details) <= 280),
    status      text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'DISMISSED', 'ACTIONED')),
    created_at  timestamptz NOT NULL,
    resolved_at timestamptz,
    resolved_by text
);
CREATE UNIQUE INDEX reports_one_open ON reports (reporter_id, target_type, target_id) WHERE status = 'OPEN';
CREATE INDEX reports_target_idx ON reports (target_type, target_id);

CREATE TABLE blocks (
    blocker_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    blocked_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL,
    PRIMARY KEY (blocker_id, blocked_id),
    CHECK (blocker_id <> blocked_id)
);
CREATE INDEX blocks_blocked_idx ON blocks (blocked_id);

-- Every operator action from the moderation CLI.
CREATE TABLE moderation_actions (
    id          uuid PRIMARY KEY,
    operator    text NOT NULL,
    action      text NOT NULL,
    target_type text NOT NULL,
    target_id   text NOT NULL,
    reason      text,
    created_at  timestamptz NOT NULL
);

-- Append-only audit trail: moderation, automatic hiding, account and room deletion.
CREATE TABLE audit_log (
    id          bigserial PRIMARY KEY,
    actor       text NOT NULL,
    action      text NOT NULL,
    target_type text,
    target_id   text,
    details     jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL
);
CREATE INDEX audit_log_created_idx ON audit_log (created_at);

-- Fixed-window rate limit and quota events. Shared by every API instance; purged after 48 hours.
CREATE TABLE rate_events (
    id          bigserial PRIMARY KEY,
    bucket      text NOT NULL,
    subject     text NOT NULL,
    amount      bigint NOT NULL DEFAULT 1 CHECK (amount >= 0),
    occurred_at timestamptz NOT NULL
);
CREATE INDEX rate_events_lookup_idx ON rate_events (bucket, subject, occurred_at);
CREATE INDEX rate_events_age_idx ON rate_events (occurred_at);
